const lessons=[{"sentences":[{"speaker":"A","text":"We need to finalize our transportation plan for the apartment move next weekend.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.14675},{"speaker":"B","text":"I checked rental prices yesterday because large vans were completely booked online.","position":2,"audioStartSeconds":5.34675,"audioEndSeconds":10.63525},{"speaker":"A","text":"Although hiring a professional moving truck is expensive, it saves us multiple trips.","position":3,"audioStartSeconds":10.83525,"audioEndSeconds":16.570541666666667},{"speaker":"B","text":"That is true since our sofa and heavy bookshelves will never fit into my small car.","position":4,"audioStartSeconds":16.770541666666666,"audioEndSeconds":22.054833333333335},{"speaker":"A","text":"Let us book the medium truck from the agency near the central station.","position":5,"audioStartSeconds":22.254833333333334,"audioEndSeconds":26.752291666666668},{"speaker":"B","text":"I can reserve that vehicle online if you provide your credit card details.","position":6,"audioStartSeconds":26.952291666666667,"audioEndSeconds":31.810541666666666},{"speaker":"A","text":"I will send those numbers to you as soon as we finish this coffee.","position":7,"audioStartSeconds":32.01054166666667,"audioEndSeconds":36.30175},{"speaker":"B","text":"Wonderful because we also need to discuss who handles the fragile packing materials.","position":8,"audioStartSeconds":36.50175,"audioEndSeconds":41.772375},{"speaker":"A","text":"If you buy enough bubble wrap, I will carefully pack all the kitchen glassware.","position":9,"audioStartSeconds":41.972375,"audioEndSeconds":46.933708333333335},{"speaker":"B","text":"That division of labor works well since glassware always requires very careful handling.","position":10,"audioStartSeconds":47.13370833333333,"audioEndSeconds":52.739375},{"speaker":"A","text":"We should collect sturdy cardboard boxes from the local grocery store this evening.","position":11,"audioStartSeconds":52.939375,"audioEndSeconds":57.97804166666667},{"speaker":"B","text":"The manager there usually throws away empty containers after closing time.","position":12,"audioStartSeconds":58.178041666666665,"audioEndSeconds":63.0105},{"speaker":"A","text":"When we arrive at the store tonight, I will ask the staff for twenty boxes.","position":13,"audioStartSeconds":63.2105,"audioEndSeconds":68.17183333333334},{"speaker":"B","text":"Twenty should be enough if we pack everything tightly and efficiently together.","position":14,"audioStartSeconds":68.37183333333333,"audioEndSeconds":73.15275},{"speaker":"A","text":"Let us meet outside the grocery store at seven o'clock sharp.","position":15,"audioStartSeconds":73.35275,"audioEndSeconds":77.47970833333333},{"speaker":"B","text":"I will drive straight from my office and meet you right on time.","position":16,"audioStartSeconds":77.67970833333334,"audioEndSeconds":81.636125}],"questions":[{"prompt":"What is the primary purpose of this conversation?","options":["To plan transportation and packing for a move.","To complain about expensive rental truck prices.","To purchase new furniture for an apartment."],"answer":"A","evidenceSentence":1,"evidence":"finalize our transportation plan for the apartment move","explanation":"Hai người bạn đang thảo luận để chốt kế hoạch vận chuyển và đóng gói cho việc chuyển nhà."},{"prompt":"Why do they decide to rent a medium truck?","options":["Small cars are too expensive to drive.","Large vans were already fully booked.","Heavy items will not fit in a small car."],"answer":"C","evidenceSentence":4,"evidence":"our sofa and heavy bookshelves will never fit into my small car","explanation":"Họ quyết định thuê xe tải vì ghế sofa và giá sách nặng không thể vừa chiếc xe hơi nhỏ."},{"prompt":"What will speaker A do immediately after finishing coffee?","options":["Send credit card details for the truck reservation.","Drive to the local grocery store for boxes.","Pack all the fragile kitchen glassware."],"answer":"A","evidenceSentence":7,"evidence":"I will send those numbers to you as soon as we finish this coffee","explanation":"Speaker A sẽ gửi thông tin thẻ tín dụng ngay sau khi uống xong cà phê để đặt xe."},{"prompt":"Who is responsible for packing the kitchen glassware?","options":["Speaker B because of previous experience.","Speaker A after speaker B buys bubble wrap.","Both speakers working together on the weekend."],"answer":"B","evidenceSentence":9,"evidence":"If you buy enough bubble wrap, I will carefully pack all the kitchen glassware","explanation":"Speaker A sẽ đóng gói đồ thủy tinh nhà bếp với điều kiện speaker B mua đủ túi bong bóng khí."},{"prompt":"Where do they plan to get empty cardboard boxes?","options":["From a central station agency.","From a local grocery store.","From speaker B's office building."],"answer":"B","evidenceSentence":11,"evidence":"collect sturdy cardboard boxes from the local grocery store","explanation":"Họ dự định lấy các hộp bìa cứng chắc chắn từ cửa hàng tạp hóa địa phương."},{"prompt":"What is the next action they will take this evening?","options":["Meet outside the grocery store at seven o'clock.","Begin packing books into heavy containers.","Call the truck rental agency to confirm prices."],"answer":"A","evidenceSentence":15,"evidence":"Let us meet outside the grocery store at seven o'clock sharp","explanation":"Hành động tiếp theo của họ là gặp nhau bên ngoài cửa hàng tạp hóa lúc đúng bảy giờ tối."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
